#include <stdio.h>
#include <dirent.h>

int main() {
    DIR *dir = opendir("/tmp");  // Replace "/tmp" with a valid directory path
    if (dir != NULL) {
        printf("Directory opened successfully.\n");
        closedir(dir);  // Close the directory to free resources
    } else {
        printf("Error opening directory.\n");
    }
    return 0;
}
